module DES_hash_chain(
    input  wire        clk,
    input  wire        rst_n,
    input  wire [63:0] chain_in,
    output reg  [63:0] chain_out);

    reg  [63:0] chain [0:127];

    integer     i;
    always @(posedge clk) begin
        if (!rst_n) begin
            for (i = 0; i < 128; i = i + 1) chain[i] <= 64'd0;
            chain_out <= 64'd0;
        end else begin
            chain[0] <= chain_in;
            for (i = 1; i < 128; i = i + 1) chain[i] <= chain[i-1];
            chain_out <= chain[127];
        end
    end
endmodule

